referenceSolutions.javascript:
export function solve(start, period, cancelTime, horizon) {
  const out = [];
  for (let t = start + period; t <= horizon; t += period) {
    if (cancelTime !== null && t >= cancelTime) break;
    out.push(t);
  }
  return out;
}

