export function solve(
  start: number,
  period: number,
  cancelTime: number | null,
  horizon: number,
): any {
  const out: number[] = [];
  for (let t = start + period; t <= horizon; t += period) {
    if (cancelTime !== null && t >= cancelTime) break;
    out.push(t);
  }
  return out;
}
